-- Turo Watch dashboard: price trends (us vs Edgar vs market vs Turo's dynamic price) and the price manager.
--
--   turo_price_log      every price change the manager made per rental day (imported from the old
--                       edgar-turo-watch artifact, Aug 3 - Sep 20 2026; runs since then live in turo_day_prices)
--   turo_market_daily   market medians by day (imported MARKET_HISTORY; runs add to turo_runs)
--   turo_watch_targets  competitors we track (Edgar's Tesla Model 3, and the host fleet he co-hosts in)
--   turo_competitor_prices  one row per scrape of a competitor for a date window
--   turo_price_series   view: one value per day per series, all in LISTING-PRICE dollars per day
--                       (renter-facing prices x 0.603, the same host factor the algorithm uses)

create table if not exists public.turo_price_log (
  id bigserial primary key,
  applied_at timestamptz not null,
  date date not null,
  old int, new int not null, floor int, ceiling int,
  verified boolean not null default false,
  src text not null default 'artifact',
  unique (applied_at, date)
);
create table if not exists public.turo_market_daily (
  observed_on date primary key,
  market_base numeric,          -- renter-side median $/day
  host_net int,                 -- the same in listing-price dollars
  n int,
  src text not null default 'artifact'
);
create table if not exists public.turo_watch_targets (
  id text primary key,
  label text not null,
  page_url text not null,
  vehicle text,
  chart boolean not null default true,  -- draw as a line on the trend chart
  active boolean not null default true,
  note text
);
create table if not exists public.turo_competitor_prices (
  id bigserial primary key,
  observed_at timestamptz not null default now(),
  target_id text not null references public.turo_watch_targets (id),
  car text,
  window_start date, window_end date, nights int,
  trip_total numeric,
  renter_daily numeric,
  host_equiv int,
  src text not null default 'claude-in-chrome'
);
create index if not exists turo_competitor_prices_idx on public.turo_competitor_prices (target_id, observed_at);

alter table public.turo_price_log enable row level security;
alter table public.turo_market_daily enable row level security;
alter table public.turo_watch_targets enable row level security;
alter table public.turo_competitor_prices enable row level security;
do $$ declare t text; begin
  foreach t in array array['turo_price_log','turo_market_daily','turo_watch_targets','turo_competitor_prices'] loop
    execute format('drop policy if exists %1$s_admin_read on public.%1$s', t);
    execute format('create policy %1$s_admin_read on public.%1$s for select to authenticated using (public.has_role(auth.uid(), ''admin''))', t);
  end loop;
end $$;

insert into public.turo_watch_targets (id, label, page_url, vehicle, chart, note) values
  ('edgar-model3', 'Edgar', 'https://turo.com/us/en/drivers/19176795', 'Tesla Model 3 2023', true, 'Co-host with one 2023 Tesla Model 3 near us: the direct comparison.'),
  ('edgar-host-fleet', 'Edgar''s host fleet', 'https://turo.com/us/en/host/26672918', '7 economy cars (Hyundai, Kia)', false, 'Host Edgar co-hosts with. Economy cars, a different segment: tracked, not charted.')
on conflict (id) do update set label = excluded.label, page_url = excluded.page_url, vehicle = excluded.vehicle, chart = excluded.chart, note = excluded.note;

