insert into public.turo_market_daily (observed_on, market_base, host_net, n, src)
select d, round(c / 1.10, 2), round(c / 1.10 * 0.603)::int, null, 'derived from ceiling'
from (select (applied_at at time zone 'America/Los_Angeles')::date d, max(ceiling) c from public.turo_price_log group by 1) s
on conflict do nothing;

