-- One value per day per series, listing-price dollars.
--   us    our listing price FOR that rental day (last known)
--   turo  Turo's dynamic price for that day (the floor we never go under)
--   market / edgar   what the market / Edgar charged, observed that day (converted to listing-price dollars)
create or replace view public.turo_price_series with (security_invoker = true) as
with day_prices as (
  select date, new as us, floor as turo, applied_at as at from public.turo_price_log
  union all
  select dp.date, coalesce(dp.actual, dp.applied, dp.cur), dp.floor, r.ran_at
    from public.turo_day_prices dp join public.turo_runs r on r.id = dp.run_id
   where coalesce(dp.actual, dp.applied, dp.cur) is not null
), latest as (
  select distinct on (date) date, us, turo from day_prices order by date, at desc
)
select date as day, 'us'::text as series, us::numeric as value from latest where us is not null
union all
select date, 'turo', turo from latest where turo is not null
union all
select day, 'market', avg(v) from (
  select observed_on as day, host_net::numeric as v from public.turo_market_daily where host_net is not null
  union all
  select (ran_at at time zone 'America/Los_Angeles')::date, host_net from public.turo_runs where host_net is not null
) m group by day
union all
select (observed_at at time zone 'America/Los_Angeles')::date, 'edgar', avg(host_equiv)
  from public.turo_competitor_prices where target_id = 'edgar-model3' group by 1;
grant select on public.turo_price_series to authenticated;
